<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog'
import { formatInstant } from '@/lib/time'
import { usePreferences } from '@/stores/preferences'
import { cacheCount, cacheProvider, type CacheRegion } from './cache'
defineProps<{ region?: CacheRegion }>()
const open = defineModel<boolean>({ required: true })
const { t, te, locale } = useI18n(), preferences = usePreferences()
const count = (value: unknown) => cacheCount(value, locale.value, t('monitor.cacheGovernance.unknown'))
const label = (value: string) => te('monitor.cacheGovernance.states.' + value) ? t('monitor.cacheGovernance.states.' + value) : t('monitor.cacheGovernance.unknown')
const provider = (row: CacheRegion) => te('monitor.cacheGovernance.providers.' + cacheProvider(row)) ? t('monitor.cacheGovernance.providers.' + cacheProvider(row)) : cacheProvider(row)
</script>
<template><Dialog v-model:open="open"><DialogContent class="flex max-h-[90vh] flex-col overflow-hidden sm:max-w-2xl"><DialogHeader><DialogTitle>{{ region?.name || t('monitor.cacheGovernance.details') }}</DialogTitle><DialogDescription>{{ t('monitor.cacheGovernance.regionDetailsHint') }}</DialogDescription></DialogHeader><div v-if="region" class="min-h-0 space-y-4 overflow-y-auto"><p class="break-all font-mono text-xs text-muted-foreground">{{ region.id }}</p><p v-if="region.lifecycleDescription" class="rounded-lg border bg-accent/30 p-3 text-sm leading-6">{{ region.lifecycleDescription }}</p><dl class="grid grid-cols-2 gap-3 text-sm"><div><dt class="text-muted-foreground">{{ t('monitor.cacheGovernance.kind') }}</dt><dd>{{ label(region.kind) }}</dd></div><div><dt class="text-muted-foreground">{{ t('monitor.cacheGovernance.status') }}</dt><dd>{{ label(region.state) }}</dd></div><div><dt class="text-muted-foreground">{{ t('monitor.cacheGovernance.provider') }}</dt><dd>{{ provider(region) }}</dd></div><div><dt class="text-muted-foreground">{{ t('monitor.cacheGovernance.isolation') }}</dt><dd>{{ label(region.scope) }}</dd></div><div><dt class="text-muted-foreground">{{ t('monitor.entries') }}</dt><dd>{{ count(region.observation?.snapshot.size ?? region.resource?.entries) }}</dd></div><div><dt class="text-muted-foreground">{{ t('monitor.cacheGovernance.bytes') }}</dt><dd>{{ count(region.observation?.snapshot.bytes ?? region.resource?.bytes) }}</dd></div><div v-if="region.resource"><dt class="text-muted-foreground">{{ t('monitor.cacheGovernance.resourceLimit') }}</dt><dd>{{ count(region.resource.entryLimit) }}</dd></div><div v-if="region.resource"><dt class="text-muted-foreground">{{ t('monitor.cacheGovernance.protectedEntries') }}</dt><dd>{{ count(region.resource.protectedEntries) }}</dd></div><div v-if="region.observation"><dt class="text-muted-foreground">{{ t('monitor.hits') }}</dt><dd>{{ count(region.observation.snapshot.hits) }}</dd></div><div v-if="region.observation"><dt class="text-muted-foreground">{{ t('monitor.misses') }}</dt><dd>{{ count(region.observation.snapshot.misses) }}</dd></div></dl><div class="space-y-1 text-xs text-muted-foreground"><p class="break-all">{{ t('monitor.cacheGovernance.process') }}{{ t('monitor.cacheGovernance.colon') }} {{ region.observation?.processId || region.resource?.processId || t('monitor.cacheGovernance.unknown') }}</p><p>{{ t('monitor.cacheGovernance.sampledAt') }}{{ t('monitor.cacheGovernance.colon') }} {{ formatInstant(region.observation?.sampledAt || region.resource?.sampledAt, preferences.timeZone, locale) }}</p><p>{{ t('monitor.cacheGovernance.resourceScopeHint') }}</p></div><div><p class="mb-2 text-sm font-medium">{{ t('monitor.cacheGovernance.invalidationSources') }}</p><ul class="flex flex-wrap gap-2 text-xs"><li v-for="source in region.invalidatedBy" :key="source" class="rounded border px-2 py-1">{{ source }}</li></ul></div></div></DialogContent></Dialog></template>
